import React, { useState, useMemo } from 'react';
import { Search, Clock, MapPin, User, Calendar as CalendarIcon, ShieldAlert } from 'lucide-react';

const ScheduleCalendar = ({ scheduleData = [], examDates = [] }) => {
  const [searchTerm, setSearchTerm] = useState("");
  const [activeFilters, setActiveFilters] = useState([1, 2, 3, 4, 5]);

  const rowHeight = 100; // Visual scale for the timeline

  // --- FILTER & SEARCH ---
  const filteredSchedule = useMemo(() => {
    return scheduleData.filter(item => {
      const matchesSearch = 
        item.subject_code?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        item.room?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        item.proctor?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesYear = activeFilters.includes(Number(item.year_level));
      return matchesSearch && matchesYear;
    });
  }, [searchTerm, activeFilters, scheduleData]);

  const yearStyles = {
    1: "bg-blue-50 border-blue-400 text-blue-900 shadow-blue-100",
    2: "bg-emerald-50 border-emerald-400 text-emerald-900 shadow-emerald-100",
    3: "bg-amber-50 border-amber-400 text-amber-900 shadow-amber-100",
    4: "bg-purple-50 border-purple-400 text-purple-900 shadow-purple-100",
    5: "bg-rose-50 border-rose-400 text-rose-900 shadow-rose-100",
  };

  // HELPER: Convert "08:00" string to pixel offset
  const getTopOffset = (timeStr) => {
    if (!timeStr) return 0;
    const [hrs, mins] = timeStr.split(':').map(Number);
    const startHour = 8; // Calendar starts at 8 AM
    return ((hrs - startHour) * rowHeight) + (mins * (rowHeight / 60));
  };

  // HELPER: Calculate duration-based height
  const getHeight = (start, end) => {
    if(!start || !end) return 80;
    const [sH, sM] = start.split(':').map(Number);
    const [eH, eM] = end.split(':').map(Number);
    const totalMinutes = (eH * 60 + eM) - (sH * 60 + sM);
    return Math.max(totalMinutes * (rowHeight / 60), 60);
  };

  return (
    <div className="flex flex-col w-full h-[900px] bg-white rounded-3xl shadow-2xl border border-slate-200 overflow-hidden mt-12">

      {/* TOOLBAR */}
      <div className="bg-slate-900 p-6 flex flex-wrap items-center justify-between gap-4 text-white">
        <div className="flex items-center gap-6">
          <div className="bg-blue-600 p-3 rounded-2xl"><CalendarIcon size={24}/></div>
          <div>
            <h2 className="text-xl font-black uppercase tracking-tighter">Global Examination Masterlist</h2>
            <p className="text-[10px] text-slate-400 font-bold tracking-widest uppercase">Institutional Resource View</p>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="flex bg-slate-800 p-1 rounded-xl border border-slate-700">
            {[1, 2, 3, 4, 5].map(y => (
              <button 
                key={y}
                onClick={() => setActiveFilters(prev => prev.includes(y) ? prev.filter(x => x!==y) : [...prev, y])}
                className={`px-4 py-2 rounded-lg text-[10px] font-black transition-all ${activeFilters.includes(y) ? 'bg-blue-600 text-white' : 'text-slate-500 hover:text-slate-300'}`}
              >
                YR {y}
              </button>
            ))}
          </div>
          <div className="relative w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" size={16}/>
            <input 
              placeholder="Search Subject, Room, or Proctor..." 
              className="w-full pl-10 pr-4 py-2.5 bg-slate-800 border-none rounded-xl text-xs font-bold focus:ring-2 ring-blue-500 outline-none"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>
      </div>

      {/* DATE HEADER */}
      <div className="flex bg-slate-50 border-b border-slate-200 shadow-sm">
        <div className="w-24 border-r border-slate-200 flex items-center justify-center font-black text-[9px] text-slate-400 uppercase [writing-mode:vertical-lr] rotate-180">Timeline</div>
        {examDates.map((date, idx) => (
          <div key={idx} className="flex-1 py-6 text-center border-r border-slate-200 last:border-0 bg-white">
            <p className="text-[9px] font-black text-blue-600 uppercase tracking-[0.2em] mb-1">
                {new Date(date).toLocaleDateString('en-US', { weekday: 'long' })}
            </p>
            <p className="text-3xl font-black text-slate-900 tracking-tighter">
                {new Date(date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
            </p>
          </div>
        ))}
      </div>

      {/* MAIN GRID */}
      <div className="flex-1 overflow-y-auto relative flex bg-slate-50">

        {/* TIME LABELS */}
        <div className="w-24 sticky left-0 z-40 bg-white/95 backdrop-blur-md border-r border-slate-200">
          {Array.from({ length: 15 }, (_, i) => i + 8).map(hr => (
            <div key={hr} style={{ height: rowHeight }} className="relative border-b border-slate-100 flex items-start justify-center pt-2">
              <span className="text-[11px] font-black text-slate-400">{String(hr).padStart(2, '0')}:00</span>
            </div>
          ))}
        </div>

        {/* COLUMNS */}
        <div className="flex flex-1 relative min-w-[1200px]">
          {examDates.map((date) => (
            <div key={date} className="flex-1 border-r border-slate-200 relative group bg-white/50">
              {Array.from({ length: 15 }).map((_, hr) => (
                <div key={hr} style={{ height: rowHeight }} className="border-b border-slate-100/50 w-full" />
              ))}

              {/* EXAM CARDS */}
              {filteredSchedule
                .filter(item => item.exam_date === date)
                .map((exam, i) => {
                  const isConflict = exam.hasConflict;
                  return (
                    <div
                      key={exam.id || i}
                      className={`absolute left-3 right-3 border-l-[6px] rounded-2xl p-4 shadow-xl z-10 transition-all hover:z-30 hover:-translate-y-1 cursor-pointer overflow-hidden ${isConflict ? 'bg-rose-50 border-rose-600 text-rose-950 shadow-rose-200 animate-pulse' : yearStyles[exam.year_level]}`}
                      style={{
                        top: getTopOffset(exam.start_time),
                        height: getHeight(exam.start_time, exam.end_time),
                      }}
                    >
                      <div className="flex justify-between items-start mb-2">
                          <span className={`px-2 py-1 rounded-lg text-[10px] font-black ${isConflict ? 'bg-rose-600 text-white' : 'bg-white/80'}`}>
                            {exam.dept_code} {exam.year_level}{exam.section}
                          </span>
                          {isConflict ? <ShieldAlert size={16} className="text-rose-600 animate-bounce"/> : <Clock size={14} className="opacity-40"/>}
                      </div>

                      <h4 className="text-[12px] font-black mb-3 leading-tight uppercase tracking-tight truncate">
                          {exam.subject_code}: {exam.subject_name}
                      </h4>

                      <div className="space-y-1">
                          <div className="flex items-center gap-2 text-[9px] font-black">
                              <MapPin size={12} className="text-slate-400"/>
                              ROOM {exam.room}
                          </div>
                          <div className="flex items-center gap-2 text-[9px] font-black uppercase">
                              <User size={12} className="text-slate-400"/>
                              {exam.proctor}
                          </div>
                      </div>

                      {isConflict && (
                        <div className="mt-2 pt-2 border-t border-rose-200 text-[8px] font-black italic">
                          CONFLICT WITH {exam.conflictWith || "GLOBAL"}
                        </div>
                      )}
                    </div>
                  );
                })}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default ScheduleCalendar;
